def truncate_middle(s, maxlen):
    if len(s) <= maxlen:
        return s
    if maxlen <= 3:
        return s[:maxlen]
    keep = maxlen - 3
    left = (keep + 1) // 2
    right = keep - left
    return s[:left] + '...' + (s[len(s) - right:] if right > 0 else '')

def smart_truncate(s, maxlen):
    if len(s) <= maxlen:
        return s
    limit = maxlen - 3
    if limit <= 0:
        return s[:maxlen]
    truncated = s[:limit]
    if ' ' in truncated:
        truncated = truncated[:truncated.rfind(' ')]
    return truncated + '...'

def truncate_filename(name, maxlen):
    if len(name) <= maxlen:
        return name
    if '.' in name:
        base, ext = name.rsplit('.', 1)
        ext = '.' + ext
    else:
        base, ext = name, ''
    keep = maxlen - len(ext) - 3
    if keep < 0:
        keep = 0
    return base[:keep] + '...' + ext

def clip_lines(text, maxlines):
    lines = text.split('\n')
    if len(lines) <= maxlines:
        return '\n'.join(lines)
    return '\n'.join(lines[:maxlines] + ['...'])

def abbreviate_name(name):
    parts = name.split()
    if len(parts) < 2:
        return name
    return parts[0][0].upper() + '. ' + ' '.join(parts[1:])

def drop_middle_names(name):
    parts = name.split()
    if len(parts) <= 2:
        return name
    return parts[0] + ' ' + parts[-1]

def slugify_maxlen(s, maxlen):
    import re
    slug = re.sub(r'-{2,}', '-', re.sub(r'[^a-z0-9]+', '-', s.lower().strip())).strip('-')
    if len(slug) <= maxlen:
        return slug
    truncated = slug[:maxlen]
    if '-' in truncated:
        truncated = truncated[:truncated.rfind('-')]
    return truncated.strip('-')

def camel_to_slug(s):
    import re
    s1 = re.sub(r'(?<!^)(?=[A-Z])', '-', s)
    return s1.lower()

def unique_slug(base, existing):
    if base not in existing:
        return base
    i = 2
    while f"{base}-{i}" in existing:
        i += 1
    return f"{base}-{i}"

def hashtag_from_title(s):
    words = s.split()
    return '#' + ''.join(w.capitalize() for w in words)
